func ladderLength(_ beginWord: String, _ endWord: String, _ wordList: [String]) -> Int {
    var words = Set(wordList)
    guard words.contains(endWord) else { return 0 }
    var level = [beginWord], steps = 1
    let letters = Array("abcdefghijklmnopqrstuvwxyz")
    while !level.isEmpty {
        var next: [String] = []
        for word in level {
            var chars = Array(word)
            for i in chars.indices {
                let original = chars[i]
                for l in letters where l != original {
                    chars[i] = l
                    let candidate = String(chars)
                    if candidate == endWord { return steps + 1 }
                    if words.remove(candidate) != nil { next.append(candidate) }
                }
                chars[i] = original
            }
        }
        level = next; steps += 1
    }
    return 0
}
